import {canInspectPrivate} from './hotseat.js';
import {SPIRITS,VEHICLES} from './content.js';
import {DIFFICULTIES} from './difficulty.js';
import {TALENTS} from './talents.js?v=16';
import {talentStatus} from './talent-panel.js';
import {portfolio} from './portfolio.js';
import {art,vehicleImage} from './illustrations.js';
import {eventPoseBitmap} from './portrait-renderer.js';
import {portrait} from './portraits.js';
const fmt=n=>Math.round(n).toLocaleString('zh-CN'),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function playerInfo(g,id=g.s.current){
 const p=g.s.players[id];if(!Number.isInteger(id)||!p)return null;const states=[];
 if(p.alive){if(p.skip)states.push({icon:'recover',title:`休养 ${p.skip} 回合`,text:'暂停移动，不推进出发天赋和研究进度。'});if(p.shield)states.push({icon:'shield',title:'免租已就绪',text:'抵消下一笔地产费用，触发后消耗。'});if(p.spirit)states.push({icon:p.spirit==='fortune'?'bank':p.spirit==='guardian'?'shield':'demolish',title:SPIRITS[p.spirit].name,text:SPIRITS[p.spirit].description+'。'+(p.spiritTurns===4?'当前回合及之后 3 次行动结束前生效。':`再结束 ${p.spiritTurns} 次行动后离开。`)});if(p.slowTurns)states.push({icon:'slow',title:`慢行剩余 ${p.slowTurns} 次`,text:'接下来对应次数的实际移动各走 1 格。'});if(p.forced)states.push({icon:'dice',title:`下次已指定 ${p.forced} 步`,text:'使用已指定步数，不再随机掷骰。'});if(p.reverse)states.push({icon:'turn',title:'本回合倒退',text:'沿记录的来路返回，不领取起点奖金。'});}
 const own=g.owned(p);return {p,c:g.char(p),assets:g.assets(p),stocks:portfolio(g,p),states,owned:own.length,vacant:own.filter(o=>!o.level).length,talent:talentStatus(g,p),difficulty:p.human?null:DIFFICULTIES[g.aiDifficulty(p)],location:g.tiles[p.pos].name,state:!p.alive?'已退出本局':g.s.phase==='finished'?'旅行已结束':g.s.current===id?'正在行动':'等待回合'};
}
export function playerPanel(g,id=g.s.current){const q=playerInfo(g,id);if(!q)return '<p>找不到这位奶伴。</p>';const {p,c,assets:a,talent:t}=q,skill=TALENTS[c.id],pose=eventPoseBitmap(c.id,p.alive?'idle':'sad'),profit=n=>n===null?'成本未记录':(n>0?'+':'')+fmt(n);
 if(!canInspectPrivate(g,id))return `<nav class="player-switch" aria-label="选择查看的奶伴">${g.s.players.map(other=>`<button data-act="playerView" data-id="${other.id}">${g.char(other).name}</button>`).join('')}</nav><h3>${c.name} · ${p.human?'真人':'电脑'}席位 ${id+1}</h3><p>${esc(q.location)} · ${q.state}</p><p>公开现金 ${fmt(a.cash)} · 净资产 ${fmt(a.total)} · 地产 ${q.owned} 块</p><p>手牌、持仓及账户明细仅当前真人接手后可见。</p>`;
 const money=(name,value,icon)=>`<div class="player-asset">${art(icon)}<span>${name}</span><strong>${fmt(value)}</strong></div>`;
 return `<nav class="player-switch" aria-label="选择查看的奶伴">${g.s.players.map(p=>`<button class="${p.id===id?'selected':''}" data-act="playerView" data-id="${p.id}" aria-pressed="${p.id===id}"><span>${portrait(p.character)}</span>${g.char(p).name}</button>`).join('')}</nav><section class="player-profile" style="--estate-color:${c.estateColor}"><div class="profile-model">${pose?`<img src="${pose}" alt="${c.name}形象">`:portrait(c.id)}</div><div><span class="badge">${p.human?'真人席位 '+(p.id+1):q.difficulty.name+'电脑'} · ${q.state}</span><h3>${c.name}</h3><span class="profile-color"><i style="background:${c.estateColor}"></i>地产与屋顶颜色</span><small>${p.alive?'停留在':'最后停留在'} ${esc(q.location)}</small><span class="profile-worth">净资产 <b>${fmt(a.total)}</b></span><button class="secondary" data-act="locatePlayer" data-id="${id}" ${p.alive?'':'disabled'}>在地图上定位</button></div></section><div class="player-asset-grid">${money('现金',a.cash,'bank')}${money('存款',a.deposit,'bank')}${money('地产估值',a.property,'house')}${money('股票市值',a.stocks,'stocks')}${money('交通工具估值',a.vehicle,'vehicle')}${money('贷款本金及利息',a.loan,'bank')}</div><p class="profile-account-note">净资产 = 现金 + 存款 + 地产 + 股票 + 交通工具 − 贷款。地产 ${q.owned} 块，其中空地 ${q.vacant} 块；点券 ${p.tickets}/150、卡包 ${p.cards.length}/15 不计入净资产。</p><div class="profile-stock"><span>股票浮动盈亏 <b>${profit(q.stocks.unrealized)}</b></span><span>已实现盈亏 <b>${profit(q.stocks.realized)}</b></span></div><section class="profile-talent"><h3>${skill.name}</h3><p>${skill.text}</p><strong>${esc(t.label)}</strong><small>已实际出发 ${t.count} 次${t.active&&t.cycle?' · 本周期 '+t.progress+'/'+t.cycle:''}</small>${t.notes.length?`<ul>${t.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>`:''}</section><h3>当前状态</h3><div class="profile-states">${q.states.length?q.states.map(s=>`<article>${art(s.icon)}<div><strong>${s.title}</strong><p>${s.text}</p></div></article>`).join(''):`<p class="panel-note">${p.alive?'没有额外状态，按普通规则旅行。':'已退出本局，资产与天赋不再继续经营。'}</p>`}</div><div class="profile-equipment">${p.vehicle?vehicleImage(p.vehicle):art('vehicle')}<div><h3>${VEHICLES[p.vehicle].name}</h3><p>${p.vehicle?'可选 1—'+VEHICLES[p.vehicle].dice+' 颗骰子':'每次使用 1 颗骰子'} · 当前选择 ${p.diceCount} 颗。</p></div></div>`;
}
